class Scope(val parent: Scope) {
  private val symbols = scala.collection.mutable.Map.empty[String, Symbol]
  def define(name: String, sym: Symbol): Boolean =
    if (symbols.contains(name)) false else { symbols(name) = sym; true }
  def lookup(name: String): Option[Symbol] =
    if (symbols.contains(name)) symbols.get(name)
    else Option(parent).flatMap(_.lookup(name))            // innermost outward
}
